    def to_dict(self):
        """Serialize the graph to a plain dict of builtin types.

        Returns ``{'tasks': [...], 'deps': {...}}``: ``tasks`` is the sorted
        list of ALL registered task names, and ``deps`` maps every
        registered task name to the sorted list of that task's DIRECT
        dependencies (exactly what ``dependencies(name)`` reports). The
        result contains only lists/dicts/strings, so it can be handed
        straight to ``json.dumps`` and friends.

        Deterministic and side-effect free, and a lossless round-trip:
        ``Scheduler.from_dict(s.to_dict()).to_dict() == s.to_dict()``."""
        return {
            "tasks": self.tasks(),
            "deps": {
                name: sorted(deps) for name, deps in self._deps.items()
            },
        }

    @classmethod
    def from_dict(cls, d):
        """Rebuild a Scheduler from a ``to_dict()``-style dict ``d``.

        ``d`` must map ``'tasks'`` to the collection of registered task
        names and ``'deps'`` to a dict of task name -> that task's DIRECT
        dependency names. Every name in ``'tasks'`` is registered; a task
        with no ``'deps'`` entry (or an empty one) simply has no
        dependencies. Names may appear in any order, in any iterable
        container; the rebuilt scheduler normalizes everything to its sorted
        ``to_dict()`` form, so ``from_dict(s.to_dict())`` is equivalent to
        ``s`` under every read/run API.

        The input is only read -- never mutated, and no reference to it is
        kept -- so later changes to ``d`` cannot affect the returned
        scheduler.

        Raises ValueError if ``d`` cannot describe a valid taskdag graph:
        it is not a dict carrying both ``'tasks'`` and ``'deps'`` keys, a
        ``'deps'`` key or a dependency name is not among ``'tasks'``, a task
        depends on itself, or the declared edges contain a cycle.
        (``add_dependency`` enforces the same self-dependency/cycle rules,
        so ``from_dict`` can never produce a cyclic scheduler.)"""
