            raise ValueError(
                "from_dict expects a dict with 'tasks' and 'deps' keys"
            )
        tasks = d["tasks"]
        deps = d["deps"]
        if isinstance(tasks, (str, bytes)):
            raise ValueError(
                "'tasks' must be a collection of task names, not a string"
            )
        if not isinstance(deps, dict):
            raise ValueError(
                "'deps' must map task names to collections of "
